// Package env implements the env template-function namespace.
package env

import (
	"fmt"
	stdos "os"
	stdstrings "strings"
)

// Env is the namespace struct; its methods are the template functions.
type Env struct{}

// NS returns the env namespace value.
func NS() any {
	return &Env{}
}

// Aliases returns the top-level alias functions for this namespace.
func Aliases() map[string]any {
	e := &Env{}
	return map[string]any{
		"getenv": e.Getenv,
	}
}

// getenv resolves a variable: the direct value if non-empty, otherwise the
// trimmed contents of the file named by the <key>_FILE variable, otherwise
// the default.
func getenv(key, def string) string {
	if val := stdos.Getenv(key); val != "" {
		return val
	}
	if file := stdos.Getenv(key + "_FILE"); file != "" {
		if b, err := stdos.ReadFile(file); err == nil {
			return stdstrings.TrimRight(string(b), "\r\n")
		}
	}
	return def
}

// Getenv implements env.Getenv. The first default (if any) is used when the
// variable is unset or empty; extra defaults are ignored.
func (e *Env) Getenv(key string, def ...string) string {
	d := ""
	if len(def) > 0 {
		d = def[0]
	}
	return getenv(key, d)
}

// Env implements env.Env, returning all environment variables as a map.
func (e *Env) Env() map[string]string {
	vars := stdos.Environ()
	m := make(map[string]string, len(vars))
	for _, v := range vars {
		k, val, _ := stdstrings.Cut(v, "=")
		m[k] = val
	}
	return m
}

// HasEnv implements env.HasEnv, reporting whether the variable is set
// (even to an empty string).
func (e *Env) HasEnv(key any) bool {
	_, ok := stdos.LookupEnv(fmt.Sprintf("%v", key))
	return ok
}

// ExpandEnv implements env.ExpandEnv, replacing $var and ${var} references
// using the same _FILE-aware lookup as Getenv. Undefined variables expand to
// the empty string.
func (e *Env) ExpandEnv(in any) string {
	return stdos.Expand(fmt.Sprintf("%v", in), func(key string) string {
		return getenv(key, "")
	})
}

package env

import (
	"bytes"
	"os"
	"path/filepath"
	"strings"
	"testing"
	"text/template"
)

func render(t *testing.T, tmpl string) (string, error) {
	t.Helper()
	fmap := template.FuncMap{"env": func() any { return NS() }}
	for name, fn := range Aliases() {
		fmap[name] = fn
	}
	tt, err := template.New("<arg>").Option("missingkey=error").Funcs(fmap).Parse(tmpl)
	if err != nil {
		return "", err
	}
	var buf bytes.Buffer
	err = tt.Execute(&buf, map[string]any{"Env": map[string]string{}})
	return buf.String(), err
}

// writeSecret creates a file with the given content and returns its path.
func writeSecret(t *testing.T, content string) string {
	t.Helper()
	p := filepath.Join(t.TempDir(), "secret")
	if err := os.WriteFile(p, []byte(content), 0o644); err != nil {
		t.Fatal(err)
	}
	return p
}

func TestGetenv(t *testing.T) {
	secretFile := writeSecret(t, "safe")
	multiNLFile := writeSecret(t, "safe\n\n\n")
	crlfFile := writeSecret(t, "a\r\n")
	innerWSFile := writeSecret(t, " a b \n")
	tabFile := writeSecret(t, "a\tb\n")

	tests := []struct {
		name  string
		setup map[string]string // env vars to set (empty string = set-but-empty)
		unset []string          // env vars to guarantee unset (not supported directly; use t.Setenv trick)
		tmpl  string
		want  string
	}{
		{name: "set var", setup: map[string]string{"T_USER": "alice"}, tmpl: `Hello, {{env.Getenv "T_USER"}}`, want: "Hello, alice"},
		{name: "alias getenv", setup: map[string]string{}, tmpl: `Hey, {{getenv "T_FIRSTNAME_UNSET" "you"}}!`, want: "Hey, you!"},
		{name: "unset no default", tmpl: `X{{env.Getenv "T_NOPE_UNSET"}}Y`, want: "XY"},
		{name: "unset with default", tmpl: `X{{env.Getenv "T_NOPE_UNSET" "def"}}Y`, want: "XdefY"},
		{name: "extra defaults ignored", setup: map[string]string{}, tmpl: `{{getenv "T_NOPE_UNSET" "B" "C"}}`, want: "B"},
		{name: "_FILE fallback", setup: map[string]string{"T_SECRET_FILE": secretFile}, tmpl: `Your secret is {{getenv "T_SECRET"}}`, want: "Your secret is safe"},
		{name: "_FILE fallback beats default", setup: map[string]string{"T_SECRET_FILE": secretFile}, tmpl: `{{env.Getenv "T_SECRET" "dflt"}}`, want: "safe"},
		{name: "direct var beats _FILE", setup: map[string]string{"T_SECRET": "real", "T_SECRET_FILE": secretFile}, tmpl: `{{getenv "T_SECRET"}}`, want: "real"},
		{name: "empty-set var falls back to _FILE", setup: map[string]string{"T_SECRET": "", "T_SECRET_FILE": secretFile}, tmpl: `[{{getenv "T_SECRET" "def"}}]`, want: "[safe]"},
		{name: "_FILE missing file, no default", setup: map[string]string{"T_SECRET_FILE": "/nonexistent/t-secret"}, tmpl: `[{{getenv "T_SECRET"}}]`, want: "[]"},
		{name: "_FILE missing file, with default", setup: map[string]string{"T_SECRET_FILE": "/nonexistent/t-secret"}, tmpl: `[{{getenv "T_SECRET" "dflt2"}}]`, want: "[dflt2]"},
		{name: "_FILE read error falls to default", setup: map[string]string{"T_SECRET_FILE": os.TempDir()}, tmpl: `[{{getenv "T_SECRET" "dflt"}}]`, want: "[dflt]"},
		{name: "_FILE strips trailing newlines", setup: map[string]string{"T_SECRET_FILE": multiNLFile}, tmpl: `[{{getenv "T_SECRET"}}]`, want: "[safe]"},
		{name: "_FILE strips CRLF", setup: map[string]string{"T_SECRET_FILE": crlfFile}, tmpl: `[{{getenv "T_SECRET"}}]`, want: "[a]"},
		{name: "_FILE keeps inner spaces", setup: map[string]string{"T_SECRET_FILE": innerWSFile}, tmpl: `[{{getenv "T_SECRET"}}]`, want: "[ a b ]"},
		{name: "_FILE keeps tabs", setup: map[string]string{"T_SECRET_FILE": tabFile}, tmpl: `[{{getenv "T_SECRET"}}]`, want: "[a\tb]"},
		{name: "empty var name", tmpl: `[{{getenv "" "def"}}]`, want: "[def]"},
		{name: "empty default", tmpl: `[{{getenv "T_NOPE_UNSET" ""}}]`, want: "[]"},
		{name: "pipeline", setup: map[string]string{"T_HOME": "/h"}, tmpl: `{{ "T_HOME" | env.Getenv }}`, want: "/h"},
		{name: "pipeline with default", tmpl: `{{ "T_NOPE_UNSET" | env.Getenv "dv" }}`, want: "dv"},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			for k, v := range tc.setup {
				t.Setenv(k, v)
			}
			got, err := render(t, tc.tmpl)
			if err != nil {
				t.Fatalf("unexpected error: %v", err)
			}
			if got != tc.want {
				t.Errorf("got %q, want %q", got, tc.want)
			}
		})
	}
}

func TestGetenvErrors(t *testing.T) {
	tests := []struct {
		name    string
		tmpl    string
		wantErr string
	}{
		{name: "no args", tmpl: `{{env.Getenv}}`, wantErr: "wrong number of args for Getenv: want at least 1 got 0"},
		{name: "alias no args", tmpl: `{{getenv}}`, wantErr: "wrong number of args for getenv: want at least 1 got 0"},
		{name: "non-string var", tmpl: `{{env.Getenv 5}}`, wantErr: "expected string; found 5"},
		{name: "non-string default", tmpl: `{{env.Getenv "T_NOPE_UNSET" 5}}`, wantErr: "expected string; found 5"},
		{name: "bool default", tmpl: `{{env.Getenv "T_NOPE_UNSET" true}}`, wantErr: "expected string; found true"},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			_, err := render(t, tc.tmpl)
			if err == nil {
				t.Fatal("expected error, got nil")
			}
			if !strings.Contains(err.Error(), tc.wantErr) {
				t.Errorf("error %q does not contain %q", err.Error(), tc.wantErr)
			}
		})
	}
}

func TestEnv(t *testing.T) {
	t.Setenv("T_ENV_KEY", "tval")
	got, err := render(t, `{{ env.Env.T_ENV_KEY }}`)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if got != "tval" {
		t.Errorf("got %q, want %q", got, "tval")
	}

	got, err = render(t, `{{ index env.Env "T_ENV_KEY" }}`)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if got != "tval" {
		t.Errorf("got %q, want %q", got, "tval")
	}

	got, err = render(t, `{{ printf "%T" env.Env }}`)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if got != "map[string]string" {
		t.Errorf("got %q, want map[string]string", got)
	}

	// missing key must fail (missingkey=error), like the reference binary
	_, err = render(t, `{{ env.Env.T_NOPE_UNSET_XYZ }}`)
	if err == nil {
		t.Fatal("expected error for missing key, got nil")
	}
	wantErr := `map has no entry for key "T_NOPE_UNSET_XYZ"`
	if !strings.Contains(err.Error(), wantErr) {
		t.Errorf("error %q does not contain %q", err.Error(), wantErr)
	}
}

func TestHasEnv(t *testing.T) {
	t.Setenv("T_SET", "bar")
	t.Setenv("T_EMPTY", "")
	tests := []struct {
		name  string
		tmpl  string
		want  string
	}{
		{name: "set", tmpl: `{{if env.HasEnv "T_SET"}}set{{else}}not set{{end}}`, want: "set"},
		{name: "unset", tmpl: `{{if env.HasEnv "T_NOPE_UNSET"}}set{{else}}not set{{end}}`, want: "not set"},
		{name: "empty is set", tmpl: `{{if env.HasEnv "T_EMPTY"}}EMPTY is set{{end}}`, want: "EMPTY is set"},
		{name: "pipeline", tmpl: `{{ "T_SET" | env.HasEnv }}`, want: "true"},
		{name: "numeric unset", tmpl: `{{env.HasEnv 5}}`, want: "false"},
		{name: "bool unset", tmpl: `{{env.HasEnv true}}`, want: "false"},
		{name: "float unset", tmpl: `{{env.HasEnv 5.5}}`, want: "false"},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			got, err := render(t, tc.tmpl)
			if err != nil {
				t.Fatalf("unexpected error: %v", err)
			}
			if got != tc.want {
				t.Errorf("got %q, want %q", got, tc.want)
			}
		})
	}

	t.Setenv("5", "yes")
	got, err := render(t, `{{env.HasEnv 5}}`)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if got != "true" {
		t.Errorf("got %q, want true (numeric key coerced to string)", got)
	}
}

