// Throwaway verification harness: renders the templates given as args using
// the local env package, mimicking the reference binary's CLI surface.
package main

import (
	"bytes"
	"fmt"
	"os"
	"text/template"

	"gomplate/funcs/env"
)

func main() {
	fmap := template.FuncMap{"env": func() any { return env.NS() }}
	for name, fn := range env.Aliases() {
		fmap[name] = fn
	}
	tmpl := os.Args[1]
	tt, err := template.New("<arg>").Option("missingkey=error").Funcs(fmap).Parse(tmpl)
	if err != nil {
		fmt.Fprintf(os.Stderr, "parse error: %v\n", err)
		os.Exit(1)
	}
	var buf bytes.Buffer
	if err := tt.Execute(&buf, map[string]any{"Env": map[string]string{}}); err != nil {
		fmt.Fprintf(os.Stderr, "ERR: %v\n", err)
		os.Exit(1)
	}
	os.Stdout.Write(buf.Bytes())
}

